<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Random Joke</title>
<style>
  body {font-family: Arial, sans-serif; text-align: center; margin-top: 2rem;}
  #joke {margin: 1rem 0; font-size: 1.2rem;}
  button {padding: 0.5rem 1rem; font-size: 1rem;}
</style>
</head>
<body>

<h1>Click for a Joke!</h1>
<div id="joke">Press the button to see a joke.</div>
<button id="btn">Tell me a joke</button>

<script>
const jokes = [
  "Why don’t scientists trust atoms? Because they make up everything!",
  "I told my computer I needed a break, and it said: 'No problem, I’ll go to sleep.'",
  "Why did the scarecrow win an award? Because he was outstanding in his field!",
  "What do you call fake spaghetti? An impasta!"
];

document.getElementById('btn').addEventListener('click', () => {
  const random = jokes[Math.floor(Math.random() * jokes.length)];
  document.getElementById('joke').textContent = random;
});
</script>

</body>
</html>
```

